#include <bits/stdc++.h>
using namespace std;

int n, m, maxm;
vector<vector<vector<int>>> dp;
vector<int> s;

int cal(int cur) {
    int res = 0;
    while (cur > 0) {
        res++;
        cur &= (cur - 1);
    }
    return res;
}

bool check(int a, int b, int c) {
    int res = (maxm - 1) & (b | (b << 1) | (b >> 1) | a | c);
    return res == maxm - 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;
    if (n < m) {
        int t = m;
        m = n;
        n = t;
    }

    maxm = 1 << m;
    dp.assign(n + 1, vector<vector<int>>(maxm, vector<int>(maxm, 100)));
    s.assign(maxm, 0);

    for (int i = 0; i < maxm; i++) {
        s[i] = cal(i);
        dp[0][0][i] = 0;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < maxm; j++) {
            for (int k = 0; k < maxm; k++) {
                for (int l = 0; l < maxm; l++) {
                    if (dp[i - 1][k][l] != 100 && check(k, l, j)) {
                        dp[i][l][j] = min(dp[i][l][j], dp[i - 1][k][l] + s[l]);
                    }
                }
            }
        }
    }

    int ans = 100;
    for (int i = 0; i < maxm; i++) {
        ans = min(dp[n][i][0], ans);
    }

    cout << n * m - ans << "\n";

    return 0;
}
